def lier_utilisateurs(apps, schema_editor):
    Participation = apps.get_model("meetings", "Participation")
    app_label, model_name = settings.AUTH_USER_MODEL.split(".")
    User = apps.get_model(app_label, model_name)

    par_cle = defaultdict(list)
    for u in User.objects.all():
        nom = f"{u.first_name} {u.last_name}".strip().lower()
        for cle in (u.username, u.email, nom):
            if cle:
                par_cle[cle.lower()].append(u)

    for p in Participation.objects.filter(utilisateur__isnull=True):
        candidats = par_cle.get(p.participant.strip().lower(), [])
        # On ne lie que si la correspondance est unique
        if len({u.pk for u in candidats}) == 1:
            p.utilisateur = candidats[0]
            p.save(update_fields=["utilisateur"])

